    public required string StationRef { get; set; }

    /// <summary>
    /// External id for correlation.
    /// </summary>
    [JsonPropertyName("taskId")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? TaskId { get; set; }

    /// <summary>
    /// Model id for this run; overrides the AgentDefinition's model.
    /// </summary>
    [JsonPropertyName("model")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Model { get; set; }

    /// <summary>
    /// GitHub repo in owner/name form.
    /// </summary>
    [JsonPropertyName("targetRepo")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? TargetRepo { get; set; }

    [JsonPropertyName("branch")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? Branch { get; set; }

    /// <summary>
    /// Per-run values; fill the prompt {placeholder} tokens and pass to the agent.
    /// </summary>
    [JsonPropertyName("parameters")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Dictionary<string, string>? Parameters { get; set; }

    /// <summary>
    /// Files downloaded into the workspace before the agent starts; only references travel.
    /// </summary>
    [JsonPropertyName("files")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<InputFile>? Files { get; set; }

    /// <summary>
    /// Session id of an earlier realtime run to continue: its saved conversation is restored and the definition's prompt is not sent.
    /// </summary>
    [JsonPropertyName("resumeSession")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public string? ResumeSession { get; set; }

    /// <summary>
    /// Repositories to clone for this run; when set they replace the AgentDefinition's resources.repos.
    /// </summary>
    [JsonPropertyName("repos")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public List<RepoRef>? Repos { get; set; }

    /// <summary>
    /// Conversation to continue and the id to save under; each field set here wins over the same field of the AgentDefinition's resources.conversation.
    /// </summary>
    [JsonPropertyName("conversation")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
